// lib/logo-dpl.ts
//
// A logo da DPL fica aqui, como texto (base64), em vez de um arquivo
// de imagem separado — assim o recibo nunca corre risco de gerar sem
// ela por causa de um caminho de arquivo que não existe no ambiente
// do servidor. É uma imagem pequena (poucos KB), então embutir ela
// direto no código é leve o suficiente pra não pesar.
//
// O fundo preto original foi removido antes de gerar este base64 —
// só o preto que tocava a borda da imagem virou transparente, então
// qualquer detalhe escuro que fizesse parte do desenho em si (como o
// traço embaixo do texto) continuou intacto.
const LOGO_DPL_BASE64 =
  ''

export function logoDplBuffer() {
  return Buffer.from(LOGO_DPL_BASE64, 'base64')
}